    #[derive(Clone, Debug, PartialEq)]
    pub enum Request {
        /// create a shm pool
        CreatePool {
            /// pool to create
            id: ObjectId,
            /// file descriptor for the pool
            fd: Fd,
            /// pool size, in bytes
            size: i32,
        },
        /// release the shm object
        Release,
    }

